  "bots.setup.guide.feishu.create.3":
    "여기에서 해당하는 Feishu 또는 Lark 도메인을 선택한 다음, 자격 증명을 양식에 붙여 넣으세요.",
  "bots.setup.guide.feishu.bind.1": "앱을 테넌트에 설치하고 봇과의 개인 채팅을 여세요.",
