    "모델, MCP, 명령 도구, 앱 렌더러의 외부 트래픽을 이 프록시로 라우팅합니다. 시스템 환경 변수는 읽지 않습니다. 비워 두면 해당 트래픽은 직접 연결되며, 내장 브라우저는 시스템 프록시 설정을 따릅니다. 앱을 다시 시작해야 적용됩니다.",
  "settings.httpProxyPlaceholder":
    "비워 두면 내장 브라우저가 시스템 프록시를 따릅니다(예: http://127.0.0.1:7890)",
  "settings.httpProxyNoProxy": "프록시 제외",
  "settings.httpProxyNoProxyDescription":
    "이 호스트와 일치하는 요청은 HTTP 프록시를 사용하지 않고 직접 연결됩니다. 규칙은 쉼표로 구분하세요. 앱을 다시 시작해야 적용됩니다.",
