  "settings.httpProxyCaCertPathPlaceholder": "예: /Users/name/certs/root-ca.pem",
  "settings.httpProxySavedHint":
    "네트워크 프록시 설정이 저장되었습니다. 앱을 다시 시작해야 적용됩니다.",
  "settings.desktopChromiumHardwareAcceleration": "Chrome 하드웨어 가속",
