    "닫기 버튼과 창 닫기 단축키는 창을 숨기며, 트레이에서 종료를 선택해야 앱이 종료됩니다. Windows에서는 기본으로 켜져 있으며, Linux에서는 데스크톱 환경이 시스템 트레이를 제공하는지에 따라 다릅니다.",
