  "settings.modelProvider.fieldHelp": "{field} 정보",
  "settings.modelProvider.help.contextWindow":
    "모델이 한 번에 처리할 수 있는 컨텍스트 용량(토큰 단위)입니다. ZCode는 이 값으로 컨텍스트를 관리합니다.\n모델의 실제 한도를 초과하지 마세요.",
  "settings.modelProvider.help.maxOutputTokens":
    "단일 모델 요청이 생성할 수 있는 최대 토큰 수입니다.\n모델의 실제 한도를 초과하지 마세요.",
  "settings.modelProvider.help.inputModalities":
    "모델이 받을 수 있는 콘텐츠 유형을 설정합니다.\n\n- **텍스트**: 텍스트 콘텐츠를 받습니다. 필수입니다.\n- **이미지**: 이미지 콘텐츠를 받습니다.\n- **동영상**: 동영상 콘텐츠를 받습니다.\n- **PDF**: PDF 문서를 직접 받습니다.",
  "settings.modelProvider.help.outputModalities":
    "모델 응답의 콘텐츠 유형입니다. 현재는 텍스트만 지원합니다.",
  "settings.modelProvider.help.capabilities":
    "- **구조화된 출력**: 출력 필드, 유형, 구조에 대한 JSON Schema 제약을 지원합니다.\n- **기본 웹 검색**: 모델 API에 내장된 웹 검색 기능을 지원합니다.\n- **대화 중 시스템 메시지**: 대화 도중 시스템 지시를 삽입하는 기능을 지원합니다.\n\n모델이 지원하지 않는 기능은 사용하지 마세요.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "채팅에서 사용할 수 있는 추론 수준을 설정합니다. **추론 강도가 낮은 순서에서 높은 순서로 정렬해야 합니다**.\n모델이 지원하지 않는 추론 수준은 구성하지 마세요.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "CEL 표현식을 사용하여 현재 추론 수준 `reasoningLevel`을 모델 API 요청 필드에 매핑합니다. 표현식이 반환한 JSON 객체는 전송되는 요청 본문에 병합됩니다.",
  "settings.modelProvider.help.advanced":
    "**MFJS 도구 스키마**: Moonshot Flavored JSON Schema 호환성을 사용합니다. 주로 Moonshot의 Kimi 모델 API에서 사용됩니다. 모델 API가 이 형식을 요구할 때만 사용하세요.",
  "settings.modelProvider.help.followRecommendedConfig":
    "모델 ID, Base URL, API 형식을 기준으로 권장 구성을 매칭합니다. ZCode는 권장 구성을 지속적으로 업데이트하고 자동으로 동기화합니다.\n설정을 직접 변경하면 해당 설정은 수동 관리로 전환되어 권장 구성 업데이트를 더 이상 따르지 않으며, 나머지 설정은 계속 스마트 구성으로 관리됩니다.",
